pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 lockTime, uint256 newMinSum) public {
        // Admissible: amount > 0 to trigger the re-entrancy path
        vm.assume(amount > 0);
        // Prevent overflow in unlock time arithmetic
        vm.assume(lockTime <= type(uint256).max - block.timestamp);

        // Deploy re-entrant attacker that calls SetMinSum during Collect -> call
        ReenteringCollector attacker = new ReenteringCollector(c, newMinSum);
        vm.deal(address(attacker), amount);

        // Initialize contract: set MinSum, log, and mark initialized
        vm.prank(address(this));
        c.SetMinSum(0);
        vm.prank(address(this));
        c.SetLogFile(address(0));
        vm.prank(address(this));
        c.Initialized();

        // Setup attacker state: call Put to set balance and unlockTime
        attacker.deposit{value: amount}(lockTime);

        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before potential re-entrant modification
        uint256 minSumBefore = c.MinSum();

        // Trigger Collect on attacker, which re-enters SetMinSum
        attacker.trigger();

        // General invariant: MinSum must be immutable after initialization.
        // Reference (nonReentrant_ guard active) prevents SetMinSum during re-entrant call.
        // Bug (nonReentrant_ empty) allows SetMinSum to change MinSum.
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract ReenteringCollector {
    C public target;
    uint256 public newMinSum;
    bool private attacking;

    constructor(C _target, uint256 _newMinSum) {
        target = _target;
        newMinSum = _newMinSum;
    }

    function deposit(uint256 lockTime) external payable {
        target.Put{value: msg.value}(lockTime);
    }

    function trigger() external {
        attacking = true;
        target.Collect(msg.value);
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            // Re-entrant call into modified nonReentrant_ modifier
            target.SetMinSum(newMinSum);
        }
    }
}

