        vm.prank(address(attacker));
        c.Put{value: amount}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minBefore = c.MinSum();

        // Attempt Collect from attacker; Collect calls address(attacker).call{value: amount}("")
        // which triggers attacker's receive, which calls back into c.SetMinSum(newMin) if allowed
        vm.prank(address(attacker));
        try c.Collect(amount) {
            // if success
        } catch {
            // if revert
        }

        uint256 minAfter = c.MinSum();

        // General property: If Collect does NOT revert, MinSum must remain unchanged.
        // (We check this by asserting that MinSum equals minBefore whenever Collect succeeded.
        //  We use a boolean flag captured inside try/catch.)
        // To achieve a single assertTrue, we check: if Collect succeeded, then minAfter == minBefore.
        // Since we can't access the boolean from the try/catch scope directly without a variable,
