pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 lockTime, uint256 minSum, uint256 newMinSum) public {
        // Keep amounts within a reasonable range to avoid overflow edge-cases in helpers
        am = bound(am, 1, type(uint128).max);
        lockTime = bound(lockTime, 1, 365 days);
        minSum = bound(minSum, 1, type(uint128).max);
        newMinSum = bound(newMinSum, 1, type(uint128).max);

        // Deploy an adversarial receiver that always reverts on low-level call to prevent actual ether transfer
        // This allows us to enter the Collect path without draining contract balance.
        address reverter = address(new Reverter());

        // 1. Initialize the contract through Initialized()
        //    Since we need sender to call Initialized and later Collect, use a prank on reverter address
        //    (any address works; using reverter is fine as it's an EOA for set-up purposes)
        c.Initialized(); // uses Test.sol's msg.sender (address(this)) by default

        // 2. Set the MinSum to a known value
        c.SetMinSum(minSum);

        // 3. Deposit some funds into reverter's Holder to satisfy acc.balance >= MinSum and acc.balance >= am
        vm.deal(reverter, am + 1);
        vm.prank(reverter);
        c.Put{value: am + 1}(lockTime);

        // 4. Warp past the unlock time so that block.timestamp > acc.unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // 5. Attempt Collect from reverter. The low-level call to reverter always reverts,
        //    so the balance subtraction (sub_uint256) never executes, but the state checks pass.
        //    After this call, the contract remains in its current state.
        vm.prank(reverter);
        try c.Collect(am) {} catch {}

        // 6. Record current MinSum
        uint256 minSumBefore = c.MinSum();

        // 7. Try to change MinSum using SetMinSum. Since contract is initialized,
        //    the correct version should revert here. The mutant (which reverts when NOT initialized)
        //    will succeed because the contract IS initialized, allowing MinSum to change.
        bool ok;
        try c.SetMinSum(newMinSum) { ok = true; } catch { ok = false; }

        // 8. Assertion: SetMinSum must NOT succeed (must revert) when called after initialization,
        //    regardless of previous operations, so MinSum remains unchanged.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

