pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address logAddr, uint256 lockTime) public {
        vm.assume(amount > 0);
        vm.assume(logAddr != address(this) && logAddr.code.length == 0);
        vm.assume(lockTime < type(uint256).max - block.timestamp);

        // Deploy a helper that acts as a valid LogFile contract
        LogFileHelper helper = new LogFileHelper();

        // Initialize C
        c.SetMinSum(0);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Now try to change Log to the helper's address; this will revert on the mutant but not on reference
        vm.prank(address(this));
        try c.SetLogFile(address(helper)) {} catch {}

        // Put some funds to enable Collect
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.Put{value: amount}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Collect; this will call AddMessage on whatever Log is set
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        assertTrue(success);

        // Check that messages were added to the helper if and only if SetLogFile succeeded
        // In reference: SetLogFile reverted -> Log remains logAddr -> no message in helper.
        // In mutant: SetLogFile assigned helper then reverted -> Log is helper -> AddMessage called on helper.
        // So: helper.HistoryLen() == 0 for reference, >0 for mutant.
        assertTrue(helper.HistoryLen() == 0);
    }
}

contract LogFileHelper {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        History.push(Message(_adr, _data, _val, block.timestamp));
    }

    function HistoryLen() public view returns (uint) {
        return History.length;
    }
}

