pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newLog, uint256 amount) public {
        // Bound amount to something reasonable for fuzzing
        vm.assume(amount > 0 && amount <= 1000000 ether);
        vm.assume(newLog != address(0) && newLog != address(c) && newLog != address(this));

        // Initialize the contract
        c.Initialized();

        // Record the current Log address before SetLogFile
        address logBefore = address(c.Log());

        // Call SetLogFile; it will revert because Initialized() was already called,
        // but the revert may come from the if(initialized)revert() or from the later revert().
        // We don't care whether it reverts; we only care about the effect on Log.
        try c.SetLogFile(newLog) {} catch {}

        // Now call Collect to force an interaction with Log.
        // We need to set up the caller with some balance and meet conditions.
        // First, fund the contract and caller.
        vm.deal(address(this), amount * 2);
        vm.deal(address(c), 0);

        // We need acc.balance >= MinSum, acc.balance >= _am, block.timestamp > acc.unlockTime.
        // Set MinSum small, put some funds in, advance past unlock time.
        c.SetMinSum(1); // MinSum is only settable before Initialized, need a re-deploy approach.
        // Actually MinSum can only be set before initialized; we already initialized.
        // So deploy a fresh C in setUp? No, we can't. We'll use vm.warp and put funds directly.
        // Since MinSum is 0 by default and balance must be >= MinSum, 0 balance >= 0 is true.
        // We'll put funds to set unlock time to 0, then warp past 0.
        vm.warp(1);
        vm.prank(address(this));
        c.Put{value: amount}(0);

        // Now call Collect
        vm.prank(address(this));
        try c.Collect(amount) {}
        catch {}

        // Assert: Log address after all calls is still logBefore.
        // If the mutant updated Log despite revert, this will fail.
        assertTrue(address(c.Log()) == logBefore, "Log changed despite revert");
    }
}

