pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 attackerAmt, address attacker) public {
        vm.assume(attacker != address(0) && attacker != address(c));
        vm.assume(attackerAmt > 0);

        // Deploy reentrant attacker helper
        ReentrantAttacker helper = new ReentrantAttacker(c);

        // Fund the attacker
        vm.deal(attacker, attackerAmt);

        // Set up initial state: initialize the contract first
        c.Initialized();
        c.SetMinSum(0);

        // Set LogFile to the helper's address (this is the SETTING, not the call under test)
        c.SetLogFile(address(helper));

        // Now attacker calls SetLogFile with a new arbitrary address, triggering reentrant call via the helper's receive
        helper.setTarget(address(0xdead));
        vm.prank(attacker);
        c.SetLogFile{value: attackerAmt}(address(helper));

        // After the call, check if the nonReentrant_ modifier on the reference prevents the state change
        // The buggy version without the modifier allows reentrant calls during SetLogFile
        // We assert that the balance of the contract remains unchanged (no reentrant Put succeeded) in the reference,
        // but the buggy version may have allowed a reentrant call that transferred Ether or changed state.
        // The general rule: after a call to SetLogFile, the contract's Ether balance must not increase from a reentrant Put call.
        // The reference satisfies this; the buggy version violates it for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    address public logTarget;

    constructor(C _target) {
        target = _target;
    }

    function setTarget(address _logTarget) external {
        logTarget = _logTarget;
    }

    receive() external payable {
        // Reentrant call: during SetLogFile, call Put with value
        target.Put{value: msg.value}(0);
    }
}
